package com.lovemaptually.service;
import com.lovemaptually.common.ApiException;import com.lovemaptually.dto.response.*;import com.lovemaptually.entity.*;import com.lovemaptually.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;import java.util.regex.*;import static com.lovemaptually.entity.Enums.*;
@Service @RequiredArgsConstructor
public class RecommendationService {private final RecommendationRequestRepository requests;private final RecommendationRepository recommendations;private final RelationGroupRepository groups;private final UserRepository users;private final PlaceRepository places;private final ReviewRepository reviews;private final GroupMemberRepository members;private final AccessService access;private final JdbcClient db;
 @Transactional public RecommendationAcceptedResponse create(long gid,long uid,String query){access.member(gid,uid);String region=parseRegion(query);if(region==null)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"REGION_NOT_FOUND","지역을 알아듣지 못했습니다");int count=parseCount(query),budget=parseBudget(query);List<Long> memberIds=members.findAllByGroupGroupIdAndLeftAtIsNullOrderByJoinedAt(gid).stream().map(m->m.getUser().getUserId()).toList();double cf=Math.min(1.0,reviews.countByUserUserIdIn(memberIds)/20.0);RecommendationRequest req=requests.saveAndFlush(RecommendationRequest.builder().group(groups.getReferenceById(gid)).requestedBy(users.getReferenceById(uid)).query(query).intentRegion(region).intentCount((short)count).intentBudget(budget==0?null:(short)budget).cfWeight(BigDecimal.valueOf(cf)).status(RecommendationStatus.PENDING).build());complete(req,gid,region,count,budget);return new RecommendationAcceptedResponse(req.getRequestId(),"PENDING",req.getCreatedAt());}
 private void complete(RecommendationRequest req,long gid,String region,int count,int budget){try{String sql="SELECT p.place_id,CASE WHEN gp.group_place_id IS NULL THEN 'OTHERS' ELSE 'OWN' END basis,COALESCE(sum(CASE WHEN ((ut.want_high_count>ut.want_low_count AND pt.fact_high_count>=pt.fact_low_count) OR (ut.want_low_count>ut.want_high_count AND pt.fact_low_count>=pt.fact_high_count)) THEN 1 ELSE 0 END),0) tag_score FROM places p LEFT JOIN group_places gp ON gp.place_id=p.place_id AND gp.group_id=:g LEFT JOIN place_tags pt ON pt.place_id=p.place_id LEFT JOIN user_tags ut ON ut.tag_id=pt.tag_id AND ut.user_id IN(SELECT user_id FROM group_members WHERE group_id=:g AND left_at IS NULL) WHERE p.region=:r"+(budget==0?"":" AND p.price_band<=:b")+" GROUP BY p.place_id,gp.group_place_id ORDER BY tag_score DESC,p.place_id LIMIT :lim";var q=db.sql(sql).param("g",gid).param("r",region).param("lim",count);if(budget!=0)q=q.param("b",budget);List<Map<String,Object>> candidates=q.query().listOfRows();short order=1;for(var c:candidates){long pid=((Number)c.get("place_id")).longValue();List<String> matched=db.sql("SELECT t.name FROM place_tags pt JOIN tags t USING(tag_id) JOIN user_tags ut USING(tag_id) WHERE pt.place_id=:p AND ut.user_id IN(SELECT user_id FROM group_members WHERE group_id=:g AND left_at IS NULL) AND ((ut.want_high_count>ut.want_low_count AND pt.fact_high_count>=pt.fact_low_count) OR (ut.want_low_count>ut.want_high_count AND pt.fact_low_count>=pt.fact_high_count)) GROUP BY t.name LIMIT 3").param("p",pid).param("g",gid).query(String.class).list();String reason=matched.isEmpty()?region+"에서 그룹이 함께 가기 좋은 장소로 골랐습니다.":String.join(", ",matched)+" 취향과 잘 맞아 골랐습니다.";recommendations.save(Recommendation.builder().request(req).place(places.getReferenceById(pid)).matchedTags(matched.toArray(String[]::new)).basis(RecommendationBasis.valueOf((String)c.get("basis"))).reason(reason).displayOrder(order++).build());}req.setCandidateCount(candidates.size());req.setStatus(RecommendationStatus.COMPLETED);req.setCompletedAt(OffsetDateTime.now());}catch(Exception e){req.setStatus(RecommendationStatus.FAILED);req.setCompletedAt(OffsetDateTime.now());}}
 @Transactional(readOnly=true) public RecommendationResultResponse get(long id,long uid){RecommendationRequest r=requests.findDetailByRequestId(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RECOMMENDATION_REQUEST_NOT_FOUND","추천 요청을 찾을 수 없습니다"));access.member(r.getGroup().getGroupId(),uid);List<RecommendationItemResponse> items=recommendations.findAllByRequestRequestIdOrderByDisplayOrder(id).stream().map(x->{Place p=x.getPlace();return new RecommendationItemResponse(x.getRecommendationId(),p.getPlaceId(),p.getName(),p.getCategory(),p.getPriceBand(),p.getLatitude(),p.getLongitude(),x.getMatchedTags()==null?List.of():List.of(x.getMatchedTags()),x.getBasis().name(),x.getReason(),x.getDisplayOrder());}).toList();return new RecommendationResultResponse(id,r.getQuery(),new RecommendationIntentResponse(r.getIntentRegion(),r.getIntentCount(),r.getIntentBudget()),r.getCandidateCount(),r.getCfWeight(),r.getStatus().name(),items);}
 private String parseRegion(String q){return places.findRegions().stream().filter(q::contains).findFirst().orElseGet(()->{Matcher m=Pattern.compile("([\uac00-\ud7a3]{2,10})(?:에서|으로| 갈|갈 건데)").matcher(q);return m.find()?m.group(1):null;});}private int parseCount(String q){Matcher m=Pattern.compile("(\\d+)\\s*(?:곳|개)").matcher(q);return m.find()?Math.max(1,Math.min(10,Integer.parseInt(m.group(1)))):3;}private int parseBudget(String q){if(q.contains("저렴")||q.contains("가성비"))return 2;if(q.contains("고급")||q.contains("비싼"))return 4;return 0;}}
